// Lab fixtures — owner: LEAD. Real NASA rows (fixtures.json, regenerated by
// scripts/build-lab-fixtures.js) plus synthetic edge cases that exist only to
// test robustness. Synthetic planets are named as such and never leave /lab.

import nasa from './fixtures.json'

const MISSING = { value: null, status: 'missing' }

function syntheticPlanet(id, name, overrides = {}) {
  return {
    id,
    name,
    host: 'Synthetic test star',
    synthetic: true,
    radiusEarth: MISSING,
    massEarth: MISSING,
    densityGcc: MISSING,
    eqTempK: MISSING,
    insolationEarth: MISSING,
    periodDays: MISSING,
    semiMajorAxisAU: MISSING,
    eccentricity: MISSING,
    inclinationDeg: MISSING,
    periastronArgDeg: MISSING,
    periastronTimeJD: MISSING,
    transitMidJD: MISSING,
    star: {
      name: 'Synthetic test star',
      spectralType: null,
      teff: MISSING,
      radiusSun: MISSING,
      massSun: MISSING,
      lumLog: MISSING,
      metallicity: MISSING,
      ageGyr: MISSING,
    },
    discovery: { year: null, method: null, facility: null, telescope: null },
    system: { distancePc: MISSING, planetCount: null, starCount: null, raDeg: null, decDeg: null, vMag: null },
    flags: { controversial: false, ttv: false },
    ...overrides,
  }
}

export const labSource = nasa.source
export const labGeneratedAt = nasa.generatedAt

/** @type {import('../../contracts/planet.js').Planet[]} */
export const labPlanets = [
  ...nasa.planets,
  syntheticPlanet('test-all-missing', 'Synthetic test: all values missing'),
  syntheticPlanet('test-insolation-only', 'Synthetic test: insolation only', {
    insolationEarth: { value: 900, status: 'measured' },
  }),
]
